param([ValidateSet('build','safety','capture','build-ck')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-compact-decode-query-20260919-r1';$seed='D:\projects\AIMA-public-compact-suffix-query-20260919-r2';$sha='3d8f94c552ddb31baf768fda5a054e07411a429e';$bundle='D:\projects\compact-decode-query-3d8f94c.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '05c6b9a9c5fc85c83ea2f08e82aa8ca822beac9eb08e5fe01124c1d6fea7cbe0'){throw 'Bundle changed'}
