if(-not $prior.host_checks_pass -or @($prior.after_processes).Count -ne 0 -or
 -not $prior.host.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Previous model cleanup failed'}
foreach($check in $prior.host_checks.PSObject.Properties){if(-not $check.Value){throw 'Previous host check failed'}}
if(-not (Test-Path $repo)){& git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'};& git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\compact-decode-query';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\compact_decode_query_selftest.cpp';$exe=Join-Path $build 'compact-decode-query.exe';$provenance=Join-Path $build 'build-provenance.json'
$sourceInputs=@()
if($m.source_commit -ne $sha){throw 'Manifest commit mismatch'}
foreach($entry in $m.source_sha256.PSObject.Properties){
 $path=Join-Path $repo $entry.Name
 if((Get-FileHash $path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $entry.Value){throw ('Source changed: '+$entry.Name)}
 $sourceInputs+=@{file=$path;sha256=$entry.Value}
}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='D:\models\Qwen3.6-35B-A3B; original GB10 16384-prefix plus1024 suffix layer3 Q/K/V';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;purpose='Compare the original exact single-query path with compact original Q. Require complete score bits, raw PV accumulators and denominators, all outputs, unchanged inputs/guards and original GB10 captured context. KV capacity changes preserve true extents. No model output, measured memory benefit or release acceptance is claimed.'}
$safety='D:\projects\AIMA-public-native-exp2-delta-20260917\build\native-exp2-delta-test-r1\run-record.json';if((Get-FileHash $safety -Algorithm SHA256).Hash.ToLowerInvariant() -ne '46a1fbaca781b00f04c3d4e3041834e8ba438e563c4c6dc3fabafc1b22126bd2'){throw 'Full-domain prerequisite changed'}
$qkSafety='D:\projects\AIMA-public-microtile-exact-qk-20260917\build\microtile-exact-qk-test-r1\run-record.json';if((Get-FileHash $qkSafety -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'd7da7e549cdf861f246d78dbfbdcb87faf152fd1920f2d19a33b9e6f069db0c6'){throw 'QK safety prerequisite changed'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe';$spec.arguments=@('-std=c++17','-O3','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','-DQRT_CK_SM121_INTERPOLATED_EXP2=1','--offload-arch=gfx1151',$source,'-o',$exe);$timeout=240
}elseif($Action -eq 'build-ck'){
 $prerequisites=@();foreach($priorAction in @('safety','capture')){
  $path=Join-Path $repo ('build\compact-decode-query-'+$priorAction+'-r2\run-record.json')
  $prior=[IO.File]::ReadAllText($path)|ConvertFrom-Json
  if($prior.reason -ne 'completed' -or $prior.exit_code -ne 0 -or -not $prior.host_checks_pass){throw 'Provider component prerequisite failed'}
  $prerequisites+=@{file=$path;sha256=(Get-FileHash $path -Algorithm SHA256).Hash.ToLowerInvariant()}
 }
 $spec.prerequisites=$prerequisites
 $exe=Join-Path $build 'qrt_ck_fmha_sm121.dll';$provenance=Join-Path $build 'build-ck-provenance.json'
 if(Test-Path $exe){throw 'Provider artifact exists'}
 $ck='D:\projects\composable-kernel-fdf4bb7'
 $headers=@(Get-ChildItem $ck -Recurse -File|Where-Object {$_.Extension -in @('.h','.hpp','.cpp')}|Sort-Object FullName|ForEach-Object {@{file=$_.FullName.Substring($ck.Length+1);bytes=$_.Length;sha256=(Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}})
 $headerPath=Join-Path $build 'ck-source-inputs.json';[IO.File]::WriteAllText($headerPath,($headers|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
 $spec.ck_source_manifest_sha256=(Get-FileHash $headerPath -Algorithm SHA256).Hash.ToLowerInvariant();$spec.ck_source_files=$headers.Count
 $spec.executable='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
 $spec.arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',(Join-Path $repo 'scripts\baiying_build_ck_fmha_q8192.ps1'),'-CkRoot',$ck,'-Sm121InterpolatedExp2','-DppReduction','1','-CompactNormalize','1','-OutPath',$exe,'-HipccPath','C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe');$timeout=240
}else{
 $meta=[IO.File]::ReadAllText($provenance)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $meta.executable.sha256){throw 'Executable provenance mismatch'}
 foreach($file in $meta.source_inputs){if((Get-FileHash $file.file -Algorithm SHA256).Hash.ToLowerInvariant() -ne $file.sha256){throw 'Build source changed'}}
 $spec.build_provenance_sha256=(Get-FileHash $provenance -Algorithm SHA256).Hash.ToLowerInvariant()
$table='D:\projects\sm121-exp2-interpolated-b5752a88.bin';if((Get-FileHash $table -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'b5752a88488d8e6382cc99a897ef822e97758e0a782930c174954a5299126eec'){throw 'Exp2 table changed'}
 $qroot='D:\projects\suffix-attention-replay-inputs-r1'
 $q=Join-Path $qroot 'query-bf16.bin'
 $k=Join-Path $qroot 'key-bf16.bin'
 $v=Join-Path $qroot 'value-bf16.bin'
 $reference=Join-Path $qroot 'expected-output-bf16.bin'
 $inputManifest=Join-Path $qroot 'manifest.json'
 if((Get-FileHash $inputManifest -Algorithm SHA256).Hash.ToLowerInvariant() -ne '819e15c5d36e6bf1deaf862839d83365b116e39a37526f90094e9f64bce652f1'){throw 'Original GB10 manifest changed'}
 $spec.reference_manifest_sha256='819e15c5d36e6bf1deaf862839d83365b116e39a37526f90094e9f64bce652f1';$spec.reference_manifest=[IO.File]::ReadAllText($inputManifest)|ConvertFrom-Json
 $rcp='D:\projects\sm121-attention-rcp-d2e55754.bin'
 $inputs=@(@{file=$q;sha256='d4445d9a03f92b1586eec9ccd12a794e742552613ed09a3b2ca28b0847ec1612'},
 @{file=$k;sha256='dbfa44ac0e63e961397cba100589a373fda702c18121dd0ea42fbbef442310bd'},
 @{file=$v;sha256='79eed4f839c165b451e4f33a54eafd2031c2876cfd19120cce9a18e36fc464a4'},
 @{file=$reference;sha256='8e49075c5d36e29c17498f70e5bfac083f66b88d041878797c4a5f44bf8b7517'},
 @{file=$table;sha256='b5752a88488d8e6382cc99a897ef822e97758e0a782930c174954a5299126eec'},
 @{file=$rcp;sha256='d2e557543f6bc51f5141ba6414000cd8ed892e2e915eda19245c3cae22c16b39'})
 foreach($input in $inputs){if((Get-FileHash $input.file -Algorithm SHA256).Hash.ToLowerInvariant() -ne $input.sha256){throw 'Capture or table fingerprint changed'}}
 $spec.input_files=$inputs;$spec.reference_is_compute_input=$false;$spec.reference_host='gb10-4t'
 $spec.reference_context_tokens=1024;$spec.query_positions=@(16384,16415,16895,17407)
 $spec.tokens=1;$spec.repeated_rows=0;$spec.query_batch=1;$spec.same_executable_comparison=$true
 $spec.unique_original_context_cells=16384;$spec.original_single_query_arithmetic=$true
 $spec.executable=$exe;$spec.arguments=@('capture',$q,$k,$v,$reference,$table,$rcp);$timeout=[int]$m.native_timeouts_seconds.$Action
 if($Action -eq 'safety'){
  $tokens=0;$spec.tokens=0;$spec.repeated_rows=0;$spec.unique_original_context_cells=0;$spec.query_positions=@(1,17,31,8191,8192,32768,131072,262144,264735);$spec.model='none; generated attention operands';$spec.input_files=@($inputs[4],$inputs[5])
  $spec.arguments=@('safety',$table,$rcp)
 }else{
  $prior=[IO.File]::ReadAllText((Join-Path $repo 'build\compact-decode-query-safety-r2\run-record.json'))|ConvertFrom-Json
  if($prior.reason -ne 'completed' -or $prior.exit_code -ne 0 -or -not $prior.host_checks_pass){throw 'Safety prerequisite failed'}
  $spec.safety_run_sha256=(Get-FileHash (Join-Path $repo 'build\compact-decode-query-safety-r2\run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant()
 }

}
$specPath=Join-Path $build ($Action+'-spec-r2.json');$out=Join-Path $repo ('build\compact-decode-query-'+$Action+'-r2')
if((Test-Path $specPath) -or (Test-Path $out)){throw 'Evidence exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native subgroup diagnostic failed'}
if($Action.StartsWith('build')){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;dirty_tree=$false;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText($provenance,($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
 }else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 $expected=if($Action -eq 'safety'){27}else{4}
 if($reports.Count -ne $expected){throw 'Incomplete compact decode cases'}
 foreach($row in $reports){
  if($row.kind -ne 'compact_decode_query' -or $row.variants -ne 2 -or $row.attempts -ne 4 -or
   $row.query_count -ne 1 -or $row.key_tokens -ne $row.query_start+1 -or
   $row.full_query_bytes -ne ($row.key_tokens*8192L) -or $row.compact_query_bytes -ne 8192 -or
   $row.score_slots -ne ($row.key_tokens*16L) -or $row.cpu_dots -ne 128){throw 'Compact decode extent evidence failed'}
  foreach($key in @('complete_scores','raw_pv_accumulator_denominator','original_single_query_arithmetic',
    'guards_inputs_tails','nonzero_output_offset','refreshed_same_addresses')){
   if(-not $row.$key){throw ('Compact decode comparison failed: '+$key)}
  }
  if($row.model_loaded -or $row.inference_acceptance -or $row.performance_acceptance){throw 'Component scope changed'}
  if($row.complete_host_ms.Count -ne 4){throw 'Missing complete call observations'}
  foreach($elapsed in $row.complete_host_ms){if([double]::IsNaN($elapsed) -or [double]::IsInfinity($elapsed) -or $elapsed -le 0){throw 'Invalid completed host observation'}}
 }
 if($Action -eq 'safety'){
  foreach($start in @(1,17,31,8191,8192,32768,131072,262144,264735)){foreach($family in @(0,1,2)){
   if(@($reports|Where-Object {$_.query_start -eq $start -and $_.family -eq $family -and $_.gb10_context_cells -eq 0}).Count -ne 1){throw 'Missing generated shape or family'}
  }}
 }else{
  foreach($start in @(16384,16415,16895,17407)){
   if(@($reports|Where-Object {$_.query_start -eq $start -and $_.family -eq 3 -and $_.gb10_context_cells -eq 4096}).Count -ne 1){throw 'Original GB10 query coverage changed'}
  }
 }
 foreach($input in $spec.input_files){if((Get-FileHash $input.file -Algorithm SHA256).Hash.ToLowerInvariant() -ne $input.sha256){throw 'Input changed during run'}}
}
